# Completely Generated by AI

import tkinter as tk
from tkinter import ttk, messagebox
import numpy as np
import pandas as pd
import joblib

MODEL_FILE = "best_health_model.joblib"

FEATURES = [
    "Stress Level", "Quality of Sleep", "Sleep Duration", "BMI",
    "Heart Rate", "Systolic BP", "Diastolic BP"
]


def extract_probability(model, input_df):
    """
    Returns (prediction:int, probability_of_class_1:float or None).

    Handles BOTH shapes scikit-learn can return here:
      - Standard binary classifier: predict_proba -> shape (1, 2)
      - Multi-output classifier (happens if the model was trained on a
        DataFrame target like df[["SD"]] instead of a Series df["SD"]):
        predict_proba -> a LIST of arrays, one per output.
    This is what was crashing the button before: the old code assumed
    only the first shape and indexed out of range on the second.
    """
    raw_pred = model.predict(input_df)
    # Normalise prediction to a plain int regardless of output shape
    pred_array = np.asarray(raw_pred)
    prediction = int(pred_array.reshape(-1)[0])

    probability = None
    if hasattr(model, "predict_proba"):
        proba = model.predict_proba(input_df)
        # Multi-output case: list of per-output arrays -> take the first output
        if isinstance(proba, list):
            proba = proba[0]
        proba = np.asarray(proba)
        row = proba[0]
        if row.shape[0] > 1:
            probability = float(row[1]) * 100
        else:
            probability = float(row[0]) * 100

    return prediction, probability


class SleepHealthGUI:
    def __init__(self, root):
        self.root = root
        self.root.title("SleepTracker | Sleep Health Predictor")
        self.root.geometry("1000x680")
        self.root.minsize(920, 640)

        # ---- Modern palette ----
        self.bg = "#0F1115"          # near-black background for the side panel
        self.panel = "#161922"
        self.card = "#1C202B"
        self.surface = "#FFFFFF"
        self.canvas_bg = "#F5F6FA"
        self.accent = "#6C5CE7"       # soft indigo accent
        self.accent_hover = "#5A4BD4"
        self.text_dark = "#1A1D24"
        self.text_light = "#FFFFFF"
        self.muted = "#8A8F9C"
        self.muted_light = "#C6C9D2"
        self.green = "#1FA971"
        self.green_bg = "#E7F8F1"
        self.red = "#E5484D"
        self.red_bg = "#FCEBEC"
        self.field_bg = "#F0F1F6"
        self.field_border = "#E1E3EA"

        self.root.configure(bg=self.canvas_bg)

        try:
            self.model = joblib.load(MODEL_FILE)
        except FileNotFoundError:
            messagebox.showerror(
                "Model not found",
                f"'{MODEL_FILE}' was not found. Put this GUI file in the same "
                "folder as your saved model."
            )
            root.destroy()
            return

        self.entries = {}
        self.build_ui()

    # ---------------------------------------------------------------
    def build_ui(self):
        # ===== Sidebar =====
        sidebar = tk.Frame(self.root, bg=self.bg, width=320)
        sidebar.pack(side="left", fill="y")
        sidebar.pack_propagate(False)

        tk.Label(
            sidebar, text="🌙 SleepTracker", bg=self.bg, fg=self.text_light,
            font=("Segoe UI Semibold", 20, "bold")
        ).pack(anchor="w", padx=32, pady=(40, 4))

        tk.Label(
            sidebar, text="Sleep Health Predictor", bg=self.bg, fg=self.muted,
            font=("Segoe UI", 10)
        ).pack(anchor="w", padx=32, pady=(0, 30))

        tk.Label(
            sidebar, text="Check your\nsleep health", bg=self.bg,
            fg=self.text_light, justify="left", font=("Segoe UI", 26, "bold")
        ).pack(anchor="w", padx=32, pady=(0, 12))

        tk.Label(
            sidebar,
            text="Enter your sleep and health measurements to get a "
                 "prediction from your trained machine-learning model.",
            bg=self.bg, fg=self.muted_light, justify="left", wraplength=250,
            font=("Segoe UI", 10)
        ).pack(anchor="w", padx=32, pady=(0, 28))

        for icon, title, text in [
            ("💤", "SLEEP", "Duration and quality"),
            ("⚖️", "LIFESTYLE", "Stress and BMI"),
            ("❤️", "VITALS", "Heart rate and blood pressure"),
        ]:
            card = tk.Frame(sidebar, bg=self.panel, highlightbackground="#262B38",
                             highlightthickness=1)
            card.pack(fill="x", padx=24, pady=6)
            row = tk.Frame(card, bg=self.panel)
            row.pack(fill="x", padx=14, pady=10)
            tk.Label(row, text=icon, bg=self.panel, font=("Segoe UI", 12)).pack(side="left", padx=(0, 8))
            inner = tk.Frame(row, bg=self.panel)
            inner.pack(side="left")
            tk.Label(inner, text=title, bg=self.panel, fg=self.text_light,
                     font=("Segoe UI", 9, "bold")).pack(anchor="w")
            tk.Label(inner, text=text, bg=self.panel, fg=self.muted,
                     font=("Segoe UI", 9)).pack(anchor="w")

        tk.Label(
            sidebar, text="RANDOM FOREST MODEL", bg=self.bg, fg=self.accent,
            font=("Segoe UI", 8, "bold")
        ).pack(side="bottom", anchor="w", padx=32, pady=24)

        # ===== Main content =====
        main = tk.Frame(self.root, bg=self.canvas_bg)
        main.pack(side="left", fill="both", expand=True)

        content = tk.Frame(main, bg=self.canvas_bg)
        content.pack(fill="both", expand=True, padx=40, pady=36)

        tk.Label(
            content, text="Your sleep profile", bg=self.canvas_bg, fg=self.text_dark,
            font=("Segoe UI Semibold", 20, "bold")
        ).pack(anchor="w")

        tk.Label(
            content, text="Enter the seven values used by the model, then check your result.",
            bg=self.canvas_bg, fg=self.muted, font=("Segoe UI", 10)
        ).pack(anchor="w", pady=(2, 22))

        form_card = tk.Frame(content, bg=self.surface, highlightbackground=self.field_border,
                              highlightthickness=1)
        form_card.pack(fill="x")
        form = tk.Frame(form_card, bg=self.surface)
        form.pack(fill="x", padx=28, pady=26)

        fields = [
            ("Stress Level", "1 – 10"),
            ("Quality of Sleep", "1 – 10"),
            ("Sleep Duration", "hours, e.g. 7.5"),
            ("BMI", "0 = Normal · 1 = Other"),
            ("Heart Rate", "BPM, e.g. 70"),
            ("Systolic BP", "e.g. 120"),
            ("Diastolic BP", "e.g. 80"),
        ]

        for i, (label, hint) in enumerate(fields):
            row, col = divmod(i, 2)
            box = tk.Frame(form, bg=self.surface)
            box.grid(row=row, column=col, sticky="ew",
                      padx=(0, 14) if col == 0 else (14, 0), pady=9)
            form.grid_columnconfigure(col, weight=1)

            tk.Label(box, text=label, bg=self.surface, fg=self.text_dark,
                      font=("Segoe UI", 9, "bold")).pack(anchor="w")
            tk.Label(box, text=hint, bg=self.surface, fg=self.muted,
                      font=("Segoe UI", 8)).pack(anchor="w", pady=(0, 4))

            entry_wrap = tk.Frame(box, bg=self.field_bg, highlightbackground=self.field_border,
                                    highlightthickness=1)
            entry_wrap.pack(fill="x")
            entry = tk.Entry(
                entry_wrap, bg=self.field_bg, fg=self.text_dark, relief="flat",
                font=("Segoe UI", 10), highlightthickness=0
            )
            entry.pack(fill="x", ipady=8, padx=10)
            self.entries[label] = entry

        # ---- Buttons ----
        buttons = tk.Frame(content, bg=self.canvas_bg)
        buttons.pack(fill="x", pady=(20, 0))

        self.check_btn = tk.Label(
            buttons, text="CHECK MY SLEEP HEALTH", bg=self.accent, fg=self.text_light,
            font=("Segoe UI", 10, "bold"), padx=22, pady=12, cursor="hand2"
        )
        self.check_btn.pack(side="left")
        self.check_btn.bind("<Button-1>", lambda e: self.predict())
        self.check_btn.bind("<Enter>", lambda e: self.check_btn.configure(bg=self.accent_hover))
        self.check_btn.bind("<Leave>", lambda e: self.check_btn.configure(bg=self.accent))

        clear_btn = tk.Label(
            buttons, text="Clear", bg=self.field_bg, fg=self.text_dark,
            font=("Segoe UI", 9), padx=20, pady=12, cursor="hand2"
        )
        clear_btn.pack(side="left", padx=10)
        clear_btn.bind("<Button-1>", lambda e: self.clear())
        clear_btn.bind("<Enter>", lambda e: clear_btn.configure(bg="#E4E6EE"))
        clear_btn.bind("<Leave>", lambda e: clear_btn.configure(bg=self.field_bg))

        # ---- Result panel ----
        self.result_frame = tk.Frame(content, bg=self.field_bg, highlightbackground=self.field_border,
                                       highlightthickness=1)
        self.result_frame.pack(fill="x", pady=(20, 0))

        self.result_title = tk.Label(
            self.result_frame, text="Prediction will appear here",
            bg=self.field_bg, fg=self.text_dark, font=("Segoe UI", 13, "bold")
        )
        self.result_title.pack(anchor="w", padx=20, pady=(16, 2))

        self.result_detail = tk.Label(
            self.result_frame,
            text="Complete the form and select 'Check my sleep health'.",
            bg=self.field_bg, fg=self.muted, wraplength=580,
            justify="left", font=("Segoe UI", 9)
        )
        self.result_detail.pack(anchor="w", padx=20, pady=(0, 16))

        tk.Label(
            content,
            text="Educational prediction only — not a medical diagnosis.",
            bg=self.canvas_bg, fg="#A6ABB5", font=("Segoe UI", 8)
        ).pack(anchor="w", pady=(14, 0))

    # ---------------------------------------------------------------
    def number(self, label, minimum=None, maximum=None, integer=False):
        value = self.entries[label].get().strip()
        if not value:
            raise ValueError(f"Please enter {label}.")
        try:
            value = int(value) if integer else float(value)
        except ValueError:
            raise ValueError(f"{label} must be a number.")
        if minimum is not None and value < minimum:
            raise ValueError(f"{label} must be at least {minimum}.")
        if maximum is not None and value > maximum:
            raise ValueError(f"{label} must be at most {maximum}.")
        return value

    def predict(self):
        try:
            values = {
                "Stress Level": self.number("Stress Level", 1, 10, True),
                "Quality of Sleep": self.number("Quality of Sleep", 1, 10, True),
                "Sleep Duration": self.number("Sleep Duration", 0, 24),
                "BMI": self.number("BMI", 0, 1, True),
                "Heart Rate": self.number("Heart Rate", 30, 220, True),
                "Systolic BP": self.number("Systolic BP", 60, 250, True),
                "Diastolic BP": self.number("Diastolic BP", 30, 150, True),
            }

            input_df = pd.DataFrame([values], columns=FEATURES)
            prediction, probability = extract_probability(self.model, input_df)

            if prediction == 0:
                title = "✓  No sleep disorder predicted"
                detail = "Based on the values entered, the model predicts that a sleep disorder is unlikely."
                if probability is not None:
                    detail += f" Model confidence: {100 - probability:.1f}%."
                self.show_result(title, detail, self.green, self.green_bg)
            else:
                title = "⚠  Sleep disorder predicted"
                detail = "Based on the values entered, the model predicts that a sleep disorder may be present."
                if probability is not None:
                    detail += f" Model probability for a disorder: {probability:.1f}%."
                self.show_result(title, detail, self.red, self.red_bg)

        except ValueError as error:
            messagebox.showwarning("Check your inputs", str(error))
        except Exception as error:
            messagebox.showerror("Prediction error", str(error))

    def show_result(self, title, detail, accent, bg):
        self.result_frame.configure(bg=bg)
        self.result_title.configure(text=title, fg=accent, bg=bg)
        self.result_detail.configure(text=detail, bg=bg)

    def clear(self):
        for entry in self.entries.values():
            entry.delete(0, tk.END)
        self.result_frame.configure(bg=self.field_bg)
        self.result_title.configure(
            text="Prediction will appear here", fg=self.text_dark, bg=self.field_bg
        )
        self.result_detail.configure(
            text="Complete the form and select 'Check my sleep health'.",
            bg=self.field_bg
        )


if __name__ == "__main__":
    root = tk.Tk()
    SleepHealthGUI(root)
    root.mainloop()
